bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 61
docker exec "$cid" node --input-type=module -e '
import pg from "pg";
import {readFileSync} from "node:fs";
const pass=readFileSync("/run/secrets/videobot_db_password","utf8").trim();
const env=process.env;
const pool=new pg.Pool({host:env.VIDEOBOT_DB_HOST,database:env.VIDEOBOT_DB_NAME,user:env.VIDEOBOT_DB_USER,password:pass,connectionTimeoutMillis:4000,max:1});
try {
 const r=await pool.query("SELECT status,free_message_ids,paid_message_id FROM videobot_post_receipts WHERE paid_message_id=$1 OR $2::bigint=ANY(free_message_ids) OR $3::bigint=ANY(free_message_ids)",[4691,4689,4690]);
 if(r.rowCount===0)process.exitCode=71;
 else if(r.rowCount!==1)process.exitCode=72;
 else if(r.rows[0].status!=="sent")process.exitCode=73;
 else if(r.rows[0].paid_message_id==4691 && r.rows[0].free_message_ids?.includes("4689"))process.exitCode=74;
 else process.exitCode=75;
} catch(e) {process.exitCode=76} finally {await pool.end();}
'
